CREATE MEMORY TABLE SAMPLE(ID VARCHAR(16) NOT NULL PRIMARY KEY,NAME VARCHAR(50),DESCRIPTION VARCHAR(100),USE_YN CHAR(1),REG_USER VARCHAR(10))
CREATE MEMORY TABLE IDS(TABLE_NAME VARCHAR(16) NOT NULL PRIMARY KEY,NEXT_ID DECIMAL(30) NOT NULL)
CREATE MEMORY TABLE CMN_TMP_REG (  STUD_NO VARCHAR(20) NOT NULL PRIMARY KEY,  PARTY_ID VARCHAR(20) NOT NULL ,  REP_NM VARCHAR(100) NOT NULL ,  ENG_NM VARCHAR(100) ,  CHA_NM VARCHAR(100) ,  GENDER_RCD VARCHAR(10),  SSN VARCHAR(30),  STUD_DIV_RCD VARCHAR(10),  DEPT_CD VARCHAR(10),  DAY_NIGHT_DIV_RCD VARCHAR(10),  NAT_RCD VARCHAR(10),  ZIPCODE VARCHAR(10),  ADDR1 VARCHAR(500),  ADDR2 VARCHAR(500),  CLP_NO VARCHAR(30),  AEN VARCHAR(30),  EMAIL VARCHAR(50),  BANK_RCD VARCHAR(10),  ACCT_NO VARCHAR(100),  OWNER_NM VARCHAR(100),  FILE_SERIAL_NO DECIMAL(15,0),  CRT_DTHR TIMESTAMP,  CRT_USER_ID VARCHAR(50),  CRT_PGM_ID VARCHAR(50),  CRT_IP_MAC VARCHAR(50),  UPD_DTHR TIMESTAMP,  UPD_USER_ID VARCHAR(50),  UPD_PGM_ID VARCHAR(50),  UPD_IP_MAC VARCHAR(50),  ATTC_FILE_NO VARCHAR(20))
CREATE MEMORY TABLE CMN_TMP_REG_FEE (  SCH_YEAR VARCHAR(4) NOT NULL ,  SMT_RCD VARCHAR(10) NOT NULL ,  STUD_NO VARCHAR(20) NOT NULL ,  REG_CLS_RCD VARCHAR(10) NOT NULL ,  IFR_DT TIMESTAMP,  PAY_CLOSE_DT TIMESTAMP,  DIV_PAY_REQ_DT TIMESTAMP,  DIV_PAY_DESC VARCHAR(300),  DIV_PAY_TYPE_CD VARCHAR(10),  DIV_PAY_STAT_RCD VARCHAR(10),  DIV_PAY_NO VARCHAR(20),  BKG_PNT DECIMAL(15,0),  BKG_TIME DECIMAL(15,0),  REG_STUD_DIV_RCD VARCHAR(10),  REMARK VARCHAR(1000),  REF_KEY VARCHAR(50),  CRT_DTHR TIMESTAMP,  CRT_USER_ID VARCHAR(50),  CRT_PGM_ID VARCHAR(50),  CRT_IP_MAC VARCHAR(50),  UPD_DTHR TIMESTAMP,  UPD_USER_ID VARCHAR(50),  UPD_PGM_ID VARCHAR(50),  UPD_IP_MAC VARCHAR(50), PRIMARY KEY(SCH_YEAR,SMT_RCD,STUD_NO,REG_CLS_RCD))
CREATE MEMORY TABLE CMN_CODE ( CD VARCHAR(20) NOT NULL PRIMARY KEY, 	UCD VARCHAR(20), 	CD_CLS VARCHAR(20) NOT NULL , 	CD_NM VARCHAR(100) NOT NULL , 	CD_SHORT_NM VARCHAR(100), 	CD_LEN DECIMAL(10,0), 	PRT_ORD VARCHAR(20), 	EFFT_STAT_DT DATE, 	EFFT_END_DT DATE, 	CD_DESC VARCHAR(1000), 	UNIT_SYSTEM_RCD VARCHAR(20), 	USE_YN VARCHAR(1), 	CD_PRP1 VARCHAR(1000), 	CD_PRP2 VARCHAR(1000), 	CD_PRP3 VARCHAR(1000), 	CD_PRP4 VARCHAR(1000), 	CD_PRP5 VARCHAR(1000), 	CD_PRP6 VARCHAR(1000), 	CD_PRP7 VARCHAR(1000), 	CD_PRP8 VARCHAR(1000), 	CD_PRP9 VARCHAR(1000), 	CD_PRP10 VARCHAR(1000), 	CD_PRP11 VARCHAR(1000), 	CD_PRP12 VARCHAR(1000), 	CD_PRP13 VARCHAR(1000), 	CD_PRP14 VARCHAR(1000), 	CD_PRP15 VARCHAR(1000), 	CD_PRP16 VARCHAR(1000), 	CD_PRP17 VARCHAR(1000), 	CD_PRP18 VARCHAR(1000), 	CD_PRP19 VARCHAR(1000), 	CD_PRP20 VARCHAR(1000), 	CRT_DTHR TIMESTAMP, 	CRT_USER_ID VARCHAR(50), 	CRT_PGM_ID VARCHAR(50), 	CRT_IP_MAC VARCHAR(50), 	UPD_DTHR TIMESTAMP, 	UPD_USER_ID VARCHAR(50), 	UPD_PGM_ID VARCHAR(50), 	UPD_IP_MAC VARCHAR(50))
CREATE MEMORY TABLE CMN_ATTC_FILE (	ATTC_FILE_NO VARCHAR(20) NOT NULL, SEQ DECIMAL(10,0) NOT NULL ,PGM_ID VARCHAR(100),USER_ID VARCHAR(50),FILE_NM VARCHAR(100) NOT NULL ,SAVE_FILE_NM VARCHAR(100) NOT NULL ,FILE_PATH VARCHAR(100) NOT NULL ,FILE_EXT VARCHAR(100),FILE_STAT_RCD VARCHAR(20),	FILE_SIZE DECIMAL(15,3),	CRT_DTHR DATE,	CRT_USER_ID VARCHAR(50),	CRT_PGM_ID VARCHAR(50),	CRT_IP_MAC VARCHAR(50),UPD_DTHR DATE,	UPD_USER_ID VARCHAR(50),	UPD_PGM_ID VARCHAR(50),UPD_IP_MAC VARCHAR(50), PRIMARY KEY(ATTC_FILE_NO, SEQ))

